package es.riegocerca.maps;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import android.widget.Toast;
public class MainActivity extends Activity{private WebView w;private ValueCallback<Uri[]> files;private GeolocationPermissions.Callback geo;private String origin;static final int LOC=7,FILE=8;
public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setGeolocationEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);w.addJavascriptInterface(new MapsBridge(this),"AndroidMaps");w.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){Uri x=Uri.parse(u);String scheme=x.getScheme(),host=x.getHost();if("google.navigation".equalsIgnoreCase(scheme)||"geo".equalsIgnoreCase(scheme)||"www.google.com".equals(host)||"maps.google.com".equals(host)){openMaps(x);return true;}return false;}});w.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String o,GeolocationPermissions.Callback c){origin=o;geo=c;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){c.invoke(o,true,true);geo=null;}else requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);}public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=c;try{startActivityForResult(p.createIntent(),FILE);return true;}catch(Exception e){files=null;return false;}}});if(b==null)w.loadUrl("file:///android_asset/index.html");else w.restoreState(b);}
private void openMaps(Uri req){String scheme=req.getScheme();String dest=null;Uri target=req;if("http".equalsIgnoreCase(scheme)||"https".equalsIgnoreCase(scheme)){dest=req.getQueryParameter("destination");if(dest!=null&&!dest.trim().isEmpty())target=Uri.parse("google.navigation:q="+Uri.encode(dest)+"&mode=d");}Intent maps=new Intent(Intent.ACTION_VIEW,target);maps.setPackage("com.google.android.apps.maps");try{startActivity(maps);}catch(ActivityNotFoundException e){Uri fallback;if(dest!=null&&!dest.trim().isEmpty())fallback=Uri.parse("https://www.google.com/maps/dir/?api=1&destination="+Uri.encode(dest)+"&travelmode=driving");else if("google.navigation".equalsIgnoreCase(scheme)){String q=req.getSchemeSpecificPart().replaceFirst("^q=","").replace("&mode=d","");fallback=Uri.parse("https://www.google.com/maps/dir/?api=1&destination="+Uri.encode(q)+"&travelmode=driving");}else fallback=Uri.parse("https://www.google.com/maps");try{startActivity(new Intent(Intent.ACTION_VIEW,fallback));}catch(Exception ex){Toast.makeText(this,"No se pudo abrir Google Maps",Toast.LENGTH_LONG).show();}}}
public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOC&&geo!=null){boolean ok=false;for(int x:g)ok|=x==PackageManager.PERMISSION_GRANTED;geo.invoke(origin,ok,true);geo=null;origin=null;}}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==FILE&&files!=null){files.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));files=null;}}public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();}protected void onSaveInstanceState(Bundle b){w.saveState(b);super.onSaveInstanceState(b);}}
